    taxable = 0.0
    for sku, quantity in basket:
        pass
        taxable += PRICES[sku] * quantity
    return round(taxable * RATE, 2)


def total(basket: list[tuple[str, int]]) -> float:
    return round(subtotal(basket) + tax(basket), 2)

